CREATE TABLE IF NOT EXISTS principal_statistics_state (id bigint unsigned NOT NULL,legacy_upper_id bigint unsigned NOT NULL,legacy_after_id bigint unsigned NOT NULL,legacy_expected_rows bigint unsigned NOT NULL,legacy_projected_rows bigint unsigned NOT NULL,projected_head bigint unsigned NOT NULL,revision bigint unsigned NOT NULL,created_at datetime(3) NOT NULL,updated_at datetime(3) NOT NULL,PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS principal_statistics_pending (observation_id bigint unsigned NOT NULL,scope_type varchar(24) NOT NULL,scope_id bigint unsigned NOT NULL,observed_at datetime(3) NOT NULL,created_at datetime(3) NOT NULL,PRIMARY KEY(observation_id),KEY idx_principal_stats_pending_scope(scope_type,scope_id,observed_at,observation_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS principal_statistics_samples (observation_id bigint unsigned NOT NULL,scope_type varchar(24) NOT NULL,scope_id bigint unsigned NOT NULL,event_id varchar(191) NOT NULL,observed_at datetime(3) NOT NULL,active_flows bigint unsigned NOT NULL,source_digest char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_created_at datetime(3) NOT NULL,review_at datetime(3) NOT NULL,raw_retired_at datetime(3) NULL,PRIMARY KEY(observation_id),UNIQUE KEY uk_principal_stats_sample_event(scope_type,scope_id,event_id),KEY idx_principal_stats_sample_time(scope_type,scope_id,observed_at,observation_id),KEY idx_principal_stats_sample_retention(raw_retired_at,review_at,observation_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS principal_statistics_hourly (scope_type varchar(24) NOT NULL,scope_id bigint unsigned NOT NULL,hour_at datetime(3) NOT NULL,peak bigint unsigned NOT NULL,sample_count bigint unsigned NOT NULL,PRIMARY KEY(scope_type,scope_id,hour_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- The owned runner initializes one legacy MAX(id)/COUNT(*) snapshot only after
-- validating these empty tables with old writers stopped. Never seed a missing
-- recorded state/receipt as zero. Subsequent work is bounded/restartable.
